// Service worker: makes the app open and work with no internet (SECURITY.md §2.7).
// - Caches only this app's own files (never other sites, never user data, which lives in IndexedDB).
// - A new version installs in the background and waits until the person taps "Update".

// <precache> generated by `npm run precache`; do not edit by hand
const VERSION = '80708ebd8a9e';
const PRECACHE = [
  './css/base.css',
  './css/components.css',
  './css/fonts.css',
  './css/layout.css',
  './css/tokens.css',
  './fonts/atkinson-hyperlegible-mono-latin.woff2',
  './fonts/atkinson-hyperlegible-next-latin.woff2',
  './icons/apple-touch-icon.png',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon-maskable-512.png',
  './index.html',
  './js/app.js',
  './js/appStore.js',
  './js/db/indexeddb.js',
  './js/db/memory.js',
  './js/db/repository.js',
  './js/prefs-boot.js',
  './js/router.js',
  './js/services/backup.js',
  './js/services/categories.js',
  './js/services/crypto.js',
  './js/services/history.js',
  './js/services/preferences.js',
  './js/services/pwa.js',
  './js/services/validate.js',
  './js/store.js',
  './js/ui/backupReminder.js',
  './js/ui/choiceGroup.js',
  './js/ui/toast.js',
  './js/utils/contrast.js',
  './js/utils/dates.js',
  './js/utils/dom.js',
  './js/utils/id.js',
  './js/utils/money.js',
  './js/views/add.js',
  './js/views/backup.js',
  './js/views/design.js',
  './js/views/history.js',
  './js/views/home.js',
  './js/views/more.js',
  './js/views/placeholder.js',
  './manifest.json',
];
// </precache>

const CACHE = `bm-${VERSION}`;

self.addEventListener('install', (event) => {
  // cache: 'reload' skips the browser's HTTP cache, so every file comes from this exact version.
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(PRECACHE.map((url) => new Request(url, { cache: 'reload' })))));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('bm-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

// The page sends this when the person taps "Update". Only our own pages may ask.
self.addEventListener('message', (event) => {
  if (event.origin !== self.location.origin) return;
  if (event.data === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);
  // Not ours (or not a plain read): let the browser handle it normally.
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(caches.match('./index.html').then((cached) => cached ?? fetch(request)));
    return;
  }
  event.respondWith(caches.match(request, { ignoreSearch: true }).then((cached) => cached ?? fetch(request)));
});
